import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        int[] prev = new int[cols];
        int[] curr = new int[cols];
        for (int j = 0; j < cols; j++) {
            prev[j] = fs.nextInt();
        }

        int[] heights = new int[cols - 1];
        int[] stack = new int[cols];
        int answer = Math.max(rows, cols);

        for (int i = 1; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                curr[j] = fs.nextInt();
            }

            for (int j = 0; j < cols - 1; j++) {
                if (prev[j] + curr[j + 1] <= prev[j + 1] + curr[j]) {
                    heights[j]++;
                } else {
                    heights[j] = 0;
                }
            }

            int top = -1;
            for (int j = 0; j <= cols - 1; j++) {
                int currentHeight = (j == cols - 1) ? 0 : heights[j];

                while (top >= 0 && heights[stack[top]] > currentHeight) {
                    int height = heights[stack[top--]];
                    int left = (top >= 0) ? stack[top] + 1 : 0;
                    int width = j - left;
                    if (height > 0) {
                        answer = Math.max(answer, (height + 1) * (width + 1));
                    }
                }

                if (j < cols - 1) {
                    stack[++top] = j;
                }
            }

            int[] temp = prev;
            prev = curr;
            curr = temp;
        }

        System.out.println(answer);
    }
}
